SELECT YEAR(opened_date) AS opened_year, CASE WHEN sqft >= 15751 THEN 'high' WHEN sqft >= 4757 THEN 'mid' ELSE 'low' END AS sqft_bucket, MAX(sqft) - MIN(sqft) AS sqft_range, ROUND(AVG(sqft), 2) AS avg_sqft FROM stores WHERE (region IN ('East', 'Central') AND city IN ('New York', 'Bangkok', 'Chiang Mai')) OR region <> 'South' GROUP BY opened_year, sqft_bucket HAVING COUNT(DISTINCT sqft) < 5;
